<template><view class="auth-page"><view class="auth-mark">知行日知</view><view class="auth-title">创建统一学习账号</view><view class="auth-desc">一次注册，可用于所有知行学习应用</view><view class="auth-card"><view class="auth-field"><view class="auth-label">账号</view><input v-model="username" class="auth-input" placeholder-class="auth-placeholder" placeholder="设置用户名" confirm-type="next" /></view><view class="auth-field"><view class="auth-label">密码</view><input v-model="password" class="auth-input" placeholder-class="auth-placeholder" password placeholder="设置密码" confirm-type="next" /></view><view class="auth-field"><view class="auth-label">确认密码</view><input v-model="confirm" class="auth-input" placeholder-class="auth-placeholder" password placeholder="再次输入密码" confirm-type="done" @confirm="submit" /></view><view class="auth-agree" @tap="agreed = !agreed"><text class="auth-agree-box" :class="{ 'auth-agree-box-on': agreed }">{{ agreed ? '✓' : '' }}</text><view class="auth-agree-text">我已阅读并同意<text class="auth-agree-link" @tap.stop="openLegal('agreement')">《用户协议》</text>与<text class="auth-agree-link" @tap.stop="openLegal('privacy')">《隐私政策》</text></view></view><button class="auth-button" :disabled="loading" @tap="submit">{{ loading ? '注册中…' : '注册并开始学习' }}</button><view class="auth-link" @tap="back">已有账号？返回登录</view></view></view></template>
<script setup lang="ts">import { ref } from 'vue'; import Taro from '@tarojs/taro'; import { api } from '@/api'; import { setToken } from '@/utils/auth'; import { showToast } from '@/utils/platform'; const username=ref(''); const password=ref(''); const confirm=ref(''); const loading=ref(false); const agreed=ref(false); function back(){Taro.navigateBack()} function openLegal(doc:string){Taro.navigateTo({url:`/pages/legal/index?doc=${doc}`})} async function submit(){if(!username.value.trim()||!password.value||!confirm.value)return showToast('请完整填写注册信息');if(password.value!==confirm.value)return showToast('两次输入的密码不一致');if(!agreed.value)return showToast('请先阅读并同意用户协议与隐私政策');loading.value=true;const response=await api.register(username.value.trim(),password.value,confirm.value);loading.value=false;if(response.code!==0||!response.data?.access_token)return showToast(response.message||'注册失败');setToken(response.data.access_token);Taro.switchTab({url:'/pages/today/index'})}</script>
